using System;using System.Linq;using UnityEngine;using UnityEditor;
public static class InspectTreeAlpha {public static string Main(){var b=new System.Text.StringBuilder();foreach(var p in new[]{"Assets/NewMap/Textures/TFP_Atlas_1A.png","Assets/Imported/Toon Series/Toon Farm Pack/Textures/TFP_Atlas_1A.psd"}){var t=AssetDatabase.LoadAssetAtPath<Texture2D>(p);var rt=RenderTexture.GetTemporary(t.width,t.height,0,RenderTextureFormat.ARGB32);var old=RenderTexture.active;Graphics.Blit(t,rt);RenderTexture.active=rt;var tex=new Texture2D(t.width,t.height,TextureFormat.RGBA32,false);tex.ReadPixels(new Rect(0,0,t.width,t.height),0,0);tex.Apply();var px=tex.GetPixels32();b.AppendLine(p+" minAlpha="+px.Min(x=>x.a)+" cutout pixels="+px.Count(x=>x.a<128)+" / "+px.Length);RenderTexture.active=old;RenderTexture.ReleaseTemporary(rt);UnityEngine.Object.DestroyImmediate(tex);}return b.ToString();}}
